    'assets/js/ss-engine-glide.js' => ['signals' => ['html-sink', 'network'], 'reviewer' => 'SS-1361', 'review' => 'HTML-SINK: five innerHTML writes (:17, :45, :161, :389, :446), every one a CONSTANT STRING with no interpolation of any kind -- chrome for the fullscreen button, the panel shell, the viewer shell, the search form and the about link. Nothing from the page, the URL or the network reaches any of them. NETWORK: two fetches (:81, :181), both passing mode same-origin, which makes a cross-origin response unreadable whatever the URL. Every caller origin-checks first as well: the pagination click path tests link.origin !== location.origin (:153), the search path tests url.origin (:429), and the About link is only built when aboutUrl.origin matches (:439). Responses are parsed with DOMParser into a DETACHED document, never executed, and script/iframe/object/embed nodes are removed before the fragment is inserted with replaceChildren (:87-88, :186-187). What it fetches is this CMS own rendered pages. The layering is the right way round: the origin test is the policy, same-origin mode is the enforcement, and the node strip is the containment.'],
